// Assemble source clips unchanged; all motion itself was generated by Higgsfield.
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');
const ffmpeg = require('ffmpeg-static');
const root = path.resolve(process.argv[2]);
const run = JSON.parse(fs.readFileSync(path.join(root, 'generation-run.json'), 'utf8').replace(/^\uFEFF/, ''));
const clips = run.clips.filter(c => c.status === 'completed');
if (clips.length !== run.clips.length) throw new Error('Some clips are unfinished; refusing an incomplete compilation.');
for (const c of clips) if (!fs.existsSync(path.join(root, c.name + '.mp4'))) throw new Error('Missing file: ' + c.name);
fs.writeFileSync(path.join(root, 'concat.txt'), clips.map(c => `file '${c.name}.mp4'`).join('\n'));
const result = spawnSync(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-y', '-f', 'concat', '-safe', '0', '-i', path.join(root, 'concat.txt'), '-c', 'copy', '-movflags', '+faststart', path.join(root, 'HUDI-all-motions-green.mp4')], { encoding: 'utf8' });
if (result.status !== 0) throw new Error(result.stderr);
console.log(JSON.stringify({ output: path.join(root, 'HUDI-all-motions-green.mp4'), clips: clips.length, method: 'stream-copy; no generated or interpolated frames' }));
